{
  "domain": "Spanish",
  "description": "Core Spanish verbs and patterns for A2–B1 learners (ser/estar, hay, have, want, can, must, go, come, like), Latin American Spanish.",
  "terms": [
    {
      "term": "ser",
      "category": "Verb",
      "definition": "Says what or who something is: name, job, origin, or a lasting trait.",
      "example": "Soy Ana, soy de Colombia y soy enfermera. — I'm Ana, from Colombia, a nurse.",
      "mental_model": "ser is the name tag you wear every day; estar is today's status update."
    },
    {
      "term": "hay",
      "category": "Verb",
      "definition": "There is or there are: points out that something exists somewhere.",
      "example": "¿Hay una farmacia por aquí? — Is there a pharmacy around here?",
      "discussion": "Hay stays the same for one or many: hay un banco, hay dos bancos. Follow it with un, una or a number, not el or la."
    },
    {
      "term": "querer",
      "category": "Verb",
      "definition": "Want: asks for a thing, or says what you'd like to do.",
      "example": "Quiero un café con leche, por favor. — I'd like a latte, please.",
      "discussion": "At a counter, 'Quiero un…, por favor' sounds normal, not rude. 'Me da un…, por favor' is just as common."
    },
    {
      "term": "tener que + infinitivo",
      "category": "Pattern",
      "definition": "Must or have to: says something is necessary for you to do.",
      "example": "Tengo que trabajar mañana temprano. — I have to work early tomorrow.",
      "anti_example": "Not 'Tengo ir' or 'Tengo a ir': the que is required. Say 'Tengo que ir'."
    },
    {
      "term": "estar",
      "category": "Verb",
      "definition": "Tells where someone or something is, or how they feel right now.",
      "example": "Estoy en el bus y estoy cansada. — I'm on the bus, and tired.",
      "anti_example": "Not 'Mi casa es en el centro' for where your house is: say 'Mi casa está en el centro'."
    },
    {
      "term": "ir",
      "category": "Verb",
      "definition": "Go: move to another place, away from where you are now.",
      "example": "Los sábados voy al mercado. — On Saturdays I go to the market.",
      "discussion": "a + el becomes al: voy al cine, voy a la playa. And '¡Vamos!' on its own means 'Let's go!'"
    },
    {
      "term": "gustar",
      "category": "Pattern",
      "definition": "Like, turned around: the thing you like is the subject, and you come first as me or te.",
      "example": "Me gustan los tacos de mi abuela. — I like my grandma's tacos.",
      "mental_model": "Read it as 'please': me gusta el café is 'coffee pleases me', so the verb follows the coffee.",
      "anti_example": "Not 'Yo gusto los tacos': that says you please the tacos. Say 'Me gustan los tacos'."
    },
    {
      "term": "tener",
      "category": "Verb",
      "definition": "Have: owning things, plus your age and body states like hunger or cold.",
      "example": "Mi hijo tiene seis años. — My son is six.",
      "anti_example": "Not 'Soy seis años' or 'Estoy hambre': say 'Tengo seis años' and 'Tengo hambre'."
    },
    {
      "term": "poder",
      "category": "Verb",
      "definition": "Can: says you're able or allowed to do something, and makes polite requests.",
      "example": "¿Puedes mandarme el archivo hoy? — Can you send me the file today?"
    },
    {
      "term": "venir",
      "category": "Verb",
      "definition": "Come: move toward the place where the speaker is, or will be.",
      "example": "¿Vienes a mi fiesta el sábado? — Coming to my party Saturday?",
      "anti_example": "Not 'Ya vengo' when a friend calls you to the door: say 'Ya voy'. 'Ya vengo' means 'I'll be right back'."
    }
  ],
